// Progressive enhancement only. All content (hours, drinks, texts, both languages)
// is already in the HTML generated by build.py. This file adds: theme, mobile menu,
// "open now" badge, drink tabs, lightbox, map-on-click, scroll reveal.
(() => {
    document.documentElement.classList.add('js');

    const $ = (s, r = document) => r.querySelector(s);
    const $$ = (s, r = document) => [...r.querySelectorAll(s)];
    const store = {
        get: k => { try { return localStorage.getItem(k); } catch { return null; } },
        set: (k, v) => { try { localStorage.setItem(k, v); } catch { /* ignore */ } }
    };

    // UI strings, opening hours and map URL are provided by build.py in #ui-data
    let ui = {};
    try { ui = JSON.parse($('#ui-data').textContent); } catch { /* use defaults */ }
    const S = ui.strings || {};
    const HOURS = ui.hours || [];

    // ---------- Theme (system default, manual override remembered) ----------
    const darkMq = window.matchMedia('(prefers-color-scheme: dark)');
    const isDark = () => (document.documentElement.dataset.theme || (darkMq.matches ? 'dark' : 'light')) === 'dark';
    function renderTheme() {
        const btn = $('#themeBtn');
        if (!btn) return;
        btn.textContent = isDark() ? '☀' : '☾';
        btn.setAttribute('aria-label', isDark() ? S.themeLight : S.themeDark);
    }
    $('#themeBtn')?.addEventListener('click', () => {
        const next = isDark() ? 'light' : 'dark';
        document.documentElement.dataset.theme = next;
        store.set('theme', next);
        renderTheme();
    });
    darkMq.addEventListener('change', renderTheme);

    // ---------- Mobile menu ----------
    const nav = $('#nav'), menuBtn = $('#menuBtn');
    let menuOpen = false;
    function setMenu(open) {
        if (!nav) return;
        menuOpen = open;
        nav.classList.toggle('open', open);
        menuBtn.setAttribute('aria-expanded', String(open));
        menuBtn.setAttribute('aria-label', open ? S.menuClose : S.menuOpen);
        document.body.style.overflow = open ? 'hidden' : '';
    }
    if (menuBtn) menuBtn.addEventListener('click', () => setMenu(!menuOpen));
    if (nav) nav.addEventListener('click', e => { if (e.target.closest('a')) setMenu(false); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && menuOpen && menuBtn) { setMenu(false); menuBtn.focus(); } });
    window.matchMedia('(min-width: 900px)').addEventListener('change', e => { if (e.matches) setMenu(false); });

    // ---------- Header shadow ----------
    const header = $('.site-header');
    const onScroll = () => header && header.classList.toggle('scrolled', window.scrollY > 10);
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();

    // ---------- "Open now" badge + highlight today (hours table is static HTML) ----------
    const pad = n => String(n).padStart(2, '0');
    const fmt = h => { h = h % 24; return pad(Math.floor(h)) + ':' + pad(Math.round((h % 1) * 60)); };
    function isOpen(now) {
        const day = now.getDay(), h = now.getHours() + now.getMinutes() / 60;
        const today = HOURS[day];
        if (today && h >= today[0] && h < today[1]) return today[1];
        const prev = HOURS[(day + 6) % 7];
        if (prev && prev[1] > 24 && h < prev[1] - 24) return prev[1] - 24;
        return false;
    }
    function renderStatus() {
        const status = $('#status');
        if (!status || !HOURS.length) return;
        const now = new Date();
        $$('#hours tr').forEach(tr => tr.classList.toggle('today', Number(tr.dataset.d) === now.getDay()));
        const close = isOpen(now);
        status.className = 'status ' + (close ? 'open' : 'closed');
        status.textContent = close ? `${S.open} · ${S.until} ${fmt(close)}` : S.closed;
    }
    renderStatus();
    setInterval(renderStatus, 60000);

    // ---------- Drink tabs (all categories are already in the HTML) ----------
    const tabsEl = $('#drinkTabs'), menu = $('#drinks-menu');
    if (tabsEl && menu) {
        const tabs = $$('.drink-tab', tabsEl), panels = $$('.drink-panel', menu);
        tabsEl.hidden = false;
        menu.classList.add('tabs-on');
        panels.forEach(p => p.setAttribute('role', 'tabpanel'));
        const select = (tab, focus) => {
            tabs.forEach(b => {
                const on = b === tab;
                b.setAttribute('aria-selected', String(on));
                b.tabIndex = on ? 0 : -1;
            });
            panels.forEach(p => { p.hidden = p.id !== tab.getAttribute('aria-controls'); });
            if (focus) tab.focus();
        };
        tabs.forEach(b => b.addEventListener('click', () => select(b)));
        tabsEl.addEventListener('keydown', e => {
            if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
            const i = tabs.indexOf(document.activeElement);
            if (i < 0) return;
            select(tabs[(i + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length], true);
        });
        select(tabs[0]);
    }

    // ---------- Lightbox ----------
    const lb = $('#lightbox'), lbImg = $('#lbImg'), items = $$('.gallery-item');
    if (lb) {
        let idx = 0;
        const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
        function show(i, dir = 0) {
            idx = (i + items.length) % items.length;
            const img = $('img', items[idx]);
            lbImg.src = img.currentSrc || img.src;
            lbImg.alt = img.alt;
            if (dir && !reduceMotion.matches && lbImg.animate) lbImg.animate(
                [{ opacity: 0, transform: `translateX(${dir * 48}px)` }, { opacity: 1, transform: 'none' }],
                { duration: 280, easing: 'cubic-bezier(.2,.7,.2,1)' });
        }
        items.forEach((b, i) => b.addEventListener('click', () => { show(i); lb.showModal(); }));
        $('#lbClose').addEventListener('click', () => lb.close());
        $('#lbPrev').addEventListener('click', () => show(idx - 1, -1));
        $('#lbNext').addEventListener('click', () => show(idx + 1, 1));
        lb.addEventListener('click', e => { if (e.target === lb) lb.close(); });
        lb.addEventListener('keydown', e => {
            if (e.key === 'ArrowLeft') show(idx - 1, -1);
            if (e.key === 'ArrowRight') show(idx + 1, 1);
        });
        let touchX = null;
        lb.addEventListener('touchstart', e => { touchX = e.changedTouches[0].clientX; }, { passive: true });
        lb.addEventListener('touchend', e => {
            if (touchX === null) return;
            const dx = e.changedTouches[0].clientX - touchX;
            if (Math.abs(dx) > 50) show(dx < 0 ? idx + 1 : idx - 1, dx < 0 ? 1 : -1);
            touchX = null;
        });
    }

    // ---------- Map (loads only after click, for GDPR) ----------
    const mapBtn = $('#mapBtn');
    if (mapBtn) mapBtn.addEventListener('click', () => {
        const iframe = document.createElement('iframe');
        iframe.src = ui.mapUrl;
        iframe.title = S.mapTitle || 'OpenStreetMap';
        iframe.loading = 'lazy';
        iframe.referrerPolicy = 'no-referrer';
        $('#map').replaceChildren(iframe);
    });

    // ---------- Footer year ----------
    const year = $('#year');
    if (year) year.textContent = new Date().getFullYear();

    // ---------- Scroll reveal ----------
    const reveals = $$('.reveal');
    if ('IntersectionObserver' in window && !window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        const io = new IntersectionObserver(entries => entries.forEach(en => {
            if (en.isIntersecting) { en.target.classList.add('visible'); io.unobserve(en.target); }
        }), { threshold: 0.15 });
        reveals.forEach(el => io.observe(el));
    } else {
        reveals.forEach(el => el.classList.add('visible'));
    }

    renderTheme();
})();
